INSERT INTO school_extra_fee_templates (school_id, name, suggested_amount, sort_order)
SELECT * FROM (VALUES
  ('11111111-0000-0000-0000-000000000001'::uuid, 'Contribution APE', 2000::numeric, 1),
  ('11111111-0000-0000-0000-000000000001'::uuid, 'Abonnement bibliothèque', 3000::numeric, 2),
  ('11111111-0000-0000-0000-000000000001'::uuid, 'Assurance scolaire', 5000::numeric, 3),
  ('11111111-0000-0000-0000-000000000001'::uuid, 'Tenue scolaire', 15000::numeric, 4)
) AS v(school_id, name, suggested_amount, sort_order)
WHERE NOT EXISTS (
  SELECT 1 FROM school_extra_fee_templates t
  WHERE t.school_id = v.school_id AND t.name = v.name
);
